INSERT INTO series (id, name, slug, continuity, release_year, description, banner_url) VALUES
('11111111-1111-1111-1111-111111111101', 'Ben 10 (2005)', 'ben-10-2005', 'Prime Timeline', 2005, 'The original series follows 10-year-old Ben Tennyson, his cousin Gwen, and their Grandpa Max on a summer road trip where Ben discovers the Omnitrix.', '/images/series/ben-10-2005.png'),
('11111111-1111-1111-1111-111111111102', 'Ben 10: Alien Force', 'ben-10-alien-force', 'Prime Timeline', 2008, 'Set five years after the original series, a 15-year-old Ben puts the Omnitrix back on to combat a secret Highbreed invasion alongside Gwen and Kevin Levin.', '/images/series/ben-10-alien-force.png'),
('11111111-1111-1111-1111-111111111103', 'Ben 10: Ultimate Alien', 'ben-10-ultimate-alien', 'Prime Timeline', 2010, 'Following the destruction of the Omnitrix, 16-year-old Ben wields the Ultimatrix, granting evolved "Ultimate" alien forms while his secret identity is exposed to the world.', '/images/series/ben-10-ultimate-alien.png')
INSERT INTO species (id, name, homeworld, description) VALUES
('22222222-2222-2222-2222-222222222201', 'Pyronite', 'Pyros', 'Magma-based lifeforms capable of extreme pyrokinesis, flight via fire propulsion, and thermal energy manipulation.'),
('22222222-2222-2222-2222-222222222202', 'Petrosapien', 'Petropia', 'Silicon-based crystalline beings with near-invulnerable crystal bodies capable of weaponizing shards and manipulating crystal structures.'),
('22222222-2222-2222-2222-222222222203', 'Kineceleran', 'Kinet', 'Hyper-accelerated bipedal raptor-like species able to manipulate friction and run at speeds exceeding 500 mph.'),
('22222222-2222-2222-2222-222222222204', 'Methanosian', 'Methanos', 'Plant-methane humanoid beings possessing regenerative bio-matter, root control, and spontaneous combustible gas projection.'),
('22222222-2222-2222-2222-222222222205', 'Sonorosian', 'Sonorosia', 'Living silicone-based sound waves residing within containment suits, capable of sonic shouts and self-duplication.'),
('22222222-2222-2222-2222-222222222206', 'Chimera Sui Generis', 'Vilgaxia (formerly Murray)', 'Massive squid-faced conqueror species known for superhuman strength, tentacle facial dexterity, and cybernetic adaptability.'),
('22222222-2222-2222-2222-222222222207', 'Osmosian', 'Earth / Osmos V', 'Human mutants capable of absorbing matter, energy, and genetic traits from others via physical contact.'),
('22222222-2222-2222-2222-222222222208', 'Anodite / Human Hybrid', 'Earth / Anodyne', 'Beings infused with Mana (life energy), capable of reality manipulation, energy constructs, and teleportation.'),
('22222222-2222-2222-2222-222222222209', 'Tetramand', 'Khoros', 'Colossal four-armed red-skinned titans with immense kinetic punching strength.'),
('22222222-2222-2222-2222-222222222210', 'Galvanic Mechamorph', 'Galvan B', 'Liquid nanite cybernetic beings capable of merging with and upgrading machinery.'),
('22222222-2222-2222-2222-222222222211', 'Vaxasaurian', 'Terradino', 'Armored dinosaur bipeds capable of growing to 60 feet for destructive power.'),
('22222222-2222-2222-2222-222222222212', 'Necrofriggian', 'Kilmamy', 'Phantom cryo-moth organisms capable of phasing through matter and radiating freeze breath.'),
('22222222-2222-2222-2222-222222222213', 'Celestialsapien', 'Forge of Creation', 'Omnipotent cosmic beings whose bodies contain the starfield of space.'),
('22222222-2222-2222-2222-222222222214', 'Arburian Pelarota', 'Arburia', 'Mammalian organisms with heavy back plates that curl into high-speed motorized spheres.')
INSERT INTO characters (name, slug, homeworld, summary, role, status) VALUES
('Heatblast', 'heatblast', 'Pyros', 'Heatblast is the very first alien transformation Ben Tennyson unlocked from the Omnitrix in the 2005 pilot episode. A magma-based Pyronite, Heatblast commands intense fire projection, thermal absorption, and volcanic flight.', 'alien', 'published'),
('Wildmutt', 'wildmutt', 'Vulpin', 'A blind, predatory quadruped Vulpimancer. Wildmutt lacks eyes and navigates entirely using 3D thermographic gill-ports on his neck and hyper-acute senses of smell and hearing, leaping across obstacles with beast-like agility.', 'alien', 'published'),
('Diamondhead', 'diamondhead', 'Petropia', 'A crystalline titan composed of near-indestructible organic green crystal. Diamondhead can refract energy blasts, morph his hands into blades or clubs, and erupt crystalline spikes from the ground.', 'alien', 'published'),
('XLR8', 'xlr8', 'Kinet', 'A hyper-accelerated raptor-like Kineceleran. Operating with wheeled spheres on his feet and a drop-down aerodynamic face shield, XLR8 easily surpasses 500 mph and can run on water and up vertical surfaces.', 'alien', 'published'),
('Grey Matter', 'grey-matter', 'Galvan Prime', 'A 5-inch-tall Galvan endowed with colossal intellectual capacity. Grey Matter can calculate complex mathematical equations instantly, deduce technical schematics, and reconfigure machinery.', 'alien', 'published'),
('Four Arms', 'four-arms', 'Khoros', 'A colossal four-armed Tetramand warrior with armored crimson skin. Four Arms possesses astronomical upper-body lifting strength and can create sonic shockwaves by clapping all four hands together.', 'alien', 'published'),
('Stinkfly', 'stinkfly', 'Lepidopterra', 'An aerial insectoid Lepidopterran with four eye stalks, four translucent wings, and an armored stinger tail. Stinkfly projects foul, flammable, or adhesive chemical slime streams from his mouth and eyes.', 'alien', 'published'),
('Ripjaws', 'ripjaws', 'Piscciss', 'An amphibious Piscciss Volann equipped with a bioluminescent head lure, razor claws, and monstrous steel-crushing hinged jaws. He morphs his legs into a single powerful fin tail for deep underwater swimming.', 'alien', 'published'),
('Upgrade', 'upgrade', 'Galvan B', 'A Galvanic Mechamorph made of liquid nanite circuitry. Upgrade can meld with any electronic or mechanical technology to enhance and weaponize it far beyond its original factory limits.', 'alien', 'published'),
('Ghostfreak', 'ghostfreak', 'Anur Phaetos', 'An eerie Ectonurite capable of matter intangibility, invisibility, and body possession. Behind his protective outer protective shroud lies a horrifying tentacled core containing the dormant consciousness of Zs''Skayr.', 'alien', 'published'),
('Cannonbolt', 'cannonbolt', 'Arburia (Pre-destruction)', 'An armored mammalian Arburian Pelarota. Cannonbolt curls into a motorized sphere, bouncing and ricocheting off surfaces with devastating kinetic impact while deflecting lasers and explosives with ease.', 'alien', 'published'),
('Wildvine', 'wildvine', 'Flors Verdance', 'A plant-based Florauna with five vine legs, a blue eye in his chest, and venus flytrap head petals. Wildvine can extend thorny vines across long distances, regenerate severed limbs, and throw explosive seed pods.', 'alien', 'published'),
('Blitzwolfer', 'blitzwolfer', 'Luna Lobo', 'An alien werewolf Loboan scanned in the New Mexico desert. Blitzwolfer possesses quadrupedal sprinting speed, night vision, and a four-part hinged jaw that splits open to fire concussive ultrasonic howls.', 'alien', 'published'),
('Snare-oh', 'snare-oh', 'Anur Khufos', 'A mummy-like Thep Khufan composed of resilient bandage wraps and a golden pharaoh crest. Snare-oh can stretch, unravel, and shape his wraps into coils or nets, and is completely immune to toxic Corrodium radiation.', 'alien', 'published'),
('Frankenstrike', 'frankenstrike', 'Anur Transyl', 'A massive cybernetic Transylian with twin electromagnetic conductor pylons on his back. Frankenstrike channels colossal currents of lightning, clamps onto magnetic surfaces, and overpowers opponents with immense brawn.', 'alien', 'published'),
('Upchuck', 'upchuck', 'Peptos XI', 'A small green reptilian Perk Gourmand equipped with four prehensile sticky tongues and a stomach connected to a pocket dimension. Upchuck can devour any inorganic substance and spit it out as explosive green plasma.', 'alien', 'published'),
('Ditto', 'ditto', 'Hathor', 'A small, hyperactive Splixson capable of endless self-duplication. Ditto can split into dozens of identical clones that think and act independently, swarming enemies with synchronized coordination.', 'alien', 'published'),
('Eye Guy', 'eye-guy', 'Sightra', 'A humanoid Opticoid covered in dozens of blinking green eyes across his torso, shoulders, and arms. Eye Guy can see in every direction simultaneously and fires varied elemental energy beams from each ocular node.', 'alien', 'published'),
('Way Big', 'way-big', 'Cosmic Storms', 'A towering To''kustar born from turbulent cosmic storms in deep space. Standing over 100 feet tall, Way Big wields god-like physical power, shrugs off planetary weaponry, and fires a devastating cosmic ray by crossing his arms.', 'alien', 'published'),
('Spitter', 'spitter', 'Scalpasc', 'A pufferfish-like bipedal Spheroid with four sharp facial tusks. Spitter inflates his internal torso reservoir to unleash pressurized torrents of concentrated, acidic, and conductive slime that wash away enemies.', 'alien', 'published'),
('Buzzshock', 'buzzshock', 'Nosideen', 'A battery-shaped Nosedeenian creature of pure living green electricity. Buzzshock travels through electrical wires, controls power grids, discharges high-voltage lightning, and duplicates when overwhelmed.', 'alien', 'published'),
('Arctiguana', 'arctiguana', 'X''Nelli', 'A blue quadrupedal reptile of the Polar Manzardill species. Arctiguana exhales long-range cryogenic freeze vapor that solidifies raging fires, coats terrain in slick ice, and freezes giant adversaries solid in seconds.', 'alien', 'published'),
('Swampfire', 'swampfire', 'Methanos', 'A plant-methane humanoid from the recalibrated Omnitrix in Alien Force. Swampfire combines methane-fueled pyrokinesis with chlorokinetic plant manipulation, throwing fireballs, regenerating severed limbs, and controlling root networks.', 'alien', 'published'),
('Echo Echo', 'echo-echo', 'Sonorosia', 'A small Sonorosian living inside a white silicone suit. Echo Echo can duplicate rapidly into an army of copies and unleash ear-splitting acoustic sonic screams capable of shattering concrete and reflecting missiles.', 'alien', 'published'),
('Humungousaur', 'humungousaur', 'Terradino', 'A 12-foot-tall bipedal sauropod Vaxasaurian possessing immense physical strength and armored brown skin. Humungousaur can expand his biological mass and density to grow up to 60 feet tall at will.', 'alien', 'published'),
('Jetray', 'jetray', 'Aeropela', 'An aerodynamic manta-ray humanoid Aerophibian engineered for supersonic flight and hyperspace travel. Jetray fires piercing neuroshock laser beams from his eyes and prehensile tail stinger.', 'alien', 'published'),
('Big Chill', 'big-chill', 'Kilmamy', 'A phantom moth-like Necrofriggian who folds his wings into a flowing hooded cloak. Big Chill can lower his molecular density to phase through solid matter while freezing anything he passes through with sub-zero cryo breath.', 'alien', 'published'),
('Chromastone', 'chromastone', 'Petropia', 'A silicone-crystal Crystalsapien capable of absorbing nearly any electromagnetic or energy attack and channeling it into intensely bright, multicolored ultraviolet prismatic laser beams.', 'alien', 'published'),
('Brainstorm', 'brainstorm', 'Encephalonus IV', 'A giant crab-like Cerebrocrustacean possessing a massive cerebral cortex. By opening his cranial shell plates, Brainstorm emits concentrated electrical storms, creates forcefields, and calculates projectile physics in fractions of a second.', 'alien', 'published'),
('Spidermonkey', 'spidermonkey', 'Aranhaschimmia', 'A blue four-armed Arachnichimp combining acrobatic agility with arachnid attributes. Spidermonkey scales vertical walls, performs acrobatic parkour, and spins high-tensile steel-like webbing from his prehensile tail.', 'alien', 'published'),
('Goop', 'goop', 'Viscosia', 'A 200-pound shapeshifting mass of emerald slime guided by an overhead Anti-Gravity Projector. Goop can alter his chemical viscosity from sticky glue to corrosive acid, reform instantly after being destroyed, and squeeze through keyholes.', 'alien', 'published'),
('Alien X', 'alien-x', 'Forge of Creation', 'A god-like Celestialsapien with the cosmos swirling within his black body silhouette. Possessing infinite reality-warping and time-bending power, Alien X remains physically motionless until his internal conflicting personalities (Bellicus and Serena) reach consensus.', 'alien', 'published'),
('Lodestar', 'lodestar', 'Attracta', 'A Biosovortian featuring a floating magnetic metal skull between broad pincer shoulders. Lodestar commands intense magnetic forcefields to attract or repel metallic alloys, crush heavy machinery, and magnetically reassemble his own shattered body.', 'alien', 'published'),
('Rath', 'rath', 'Appoplexia', 'A bipedal tiger-like Appoplexian armed with retractable knuckle wrist blades and tremendous physical brawn. Rath is defined by his uncontrollable aggression, wrestling takedowns, and shouting catchphrases like "LET ME TELL YA SOMETHING!"', 'alien', 'published'),
('Nanomech', 'nanomech', 'Hive World / Earth', 'A microscopic biomechanical hybrid created by scanning the alien Nanochip Queen in Ben 10: Alien Swarm. Nanomech can shrink down to sub-cellular size, maneuver on humming insectoid wings, and shoot bio-electric laser bolts.', 'alien', 'published'),
('Upchuck (Murk)', 'upchuck-murk', 'Peptos XI', 'The darker-skinned, spotted subspecies of the Gourmand race. Murk Upchuck shares the same pocket-dimension stomach and explosive plasma digestion as his Perk brother, but features thicker hide and a distinct mottled appearance.', 'alien', 'published'),
('Water Hazard', 'water-hazard', 'Kiuana (Andromeda Galaxy)', 'A red armored Orishan scanned from the Andromeda fugitive Bivalvan. Water Hazard can project high-pressure boiling or cold water jets from ports in his palms, absorb ambient atmospheric moisture, and withstand physical trauma with his chitinous shell.', 'alien', 'published'),
('Terraspin', 'terraspin', 'Aldabra (Andromeda Galaxy)', 'A peaceful, turtle-like Geochelone Aerio from the Andromeda Galaxy (scanned from Galapagus). Terraspin retracts into his carapace and rotates his massive flippers like propeller blades, generating category-5 hurricanes and enjoying innate immunity to magic and mana.', 'alien', 'published'),
('NRG', 'nrg', 'Prypiatos (Andromeda Galaxy)', 'A radioactive energy being from the Andromeda Galaxy (scanned from P''andor) encased in a nearly indestructible lead furnace suit. NRG channels searing thermonuclear heat that melts rock, and can unleash his true radiant form when liberated from the suit.', 'alien', 'published'),
('AmpFibian', 'ampfibian', 'Tesslos (Andromeda Galaxy)', 'A translucent blue jellyfish-like Amperi from the Andromeda Galaxy (scanned from Ra''ad). AmpFibian floats weightlessly through air and water, shoots bio-electric arcs, reads mental nervous impulses, and travels along electrical circuits.', 'alien', 'published'),
('Armodrillo', 'armodrillo', 'Terraexcava (Andromeda Galaxy)', 'A heavy yellow armored armadillo-like Talpaedan from the Andromeda Galaxy (scanned from Andreas). Armed with pneumatic jackhammer piston forearms, Armodrillo creates earthquakes, burrows through bedrock at high speed, and pulverizes enemy defenses.', 'alien', 'published'),
('Chamalien', 'chamalien', 'Unknown (Deep Galaxy)', 'A chameleon-like Merlinisapien scanned from Prisoner 775 in Ultimate Alien. Chamalien blends seamlessly into any background, walks along ceilings, and strikes silently with a retractable venomous barb hidden inside his tail.', 'alien', 'published'),
('Fasttrack', 'fasttrack', 'Chalybeas', 'A feline Citrakayah with sleek aerodynamic black-and-blue fur and spike-tipped arms. Fasttrack combines speeds exceeding 400 mph with superior upper-body muscle density, allowing him to carry heavy allies across battlefields while sprinting.', 'alien', 'published'),
('Clockwork', 'clockwork', 'Unknown (Temporal Dimension)', 'A golden biomechanical Chronosapien filled with intricate internal chronological gears. By winding the key on his head, Clockwork can slow down time, reverse events, display holographic timelines of the past, and shoot green aging temporal rays.', 'alien', 'published'),
('Eatle', 'eatle', 'Coleop Terra', 'A metallic rhinoceros-beetle humanoid Oryctini with steel-cutting jaws. Eatle devours solid rock, metal scrap, and debris, rapidly converting the ingested matter into high-powered energy charges fired as laser beams from his massive horn.', 'alien', 'published'),
('Ultimate Swampfire', 'ultimate-swampfire', 'Methanos (Simulated War Evolution)', 'The hyper-evolved form of Swampfire through the Ultimatrix evolutionary matrix. Encased in fireproof petrified wood, Ultimate Swampfire sacrifices plant regeneration for blue thermal plasma bombs capable of underwater detonation.', 'alien', 'published'),
('Ultimate Echo Echo', 'ultimate-echo-echo', 'Sonorosia (Simulated War Evolution)', 'The hyper-evolved form of Echo Echo. Transformed into a tall, metallic blue robotic organism, Ultimate Echo Echo sacrifices biological self-duplication for dozens of levitating sonic disks that generate devastating acoustic forcefields.', 'alien', 'published'),
('Ultimate Humungousaur', 'ultimate-humungousaur', 'Terradino (Simulated War Evolution)', 'The evolved Vaxasaurian after a million years of worst-case simulated war. Featuring armored green shell-plating, a mace-spiked bone tail, and hands that transform into biological gatling missile launchers firing kinetic rocket shells.', 'alien', 'published'),
('Ultimate Spidermonkey', 'ultimate-spidermonkey', 'Aranhaschimmia (Simulated War Evolution)', 'The hyper-evolved form of Spidermonkey. Transformed from an agile monkey into a colossal gorilla-spider hybrid with eight arachnid legs, immense upper-body brawn, and the ability to shoot high-tensile steel webbing from his split mouth.', 'alien', 'published'),
('Ultimate Big Chill', 'ultimate-big-chill', 'Kilmamy (Simulated War Evolution)', 'The evolved Necrofriggian sporting crimson flame-patterned wings and fiery horns. Ultimate Big Chill can project "ice so cold it burns"—producing sub-zero cryo-flames that freeze oxygen and targets faster than standard freeze breath.', 'alien', 'published'),
('Ultimate Cannonbolt', 'ultimate-cannonbolt', 'Arburia (Simulated War Evolution)', 'The hyper-evolved Arburian Pelarota encased in a dense metallic-cyan shell studded with heavy spikes. In his rolling sphere form, Ultimate Cannonbolt digs into terrain with traction and ricochets with unstoppable kinetic crushing power.', 'alien', 'published'),
('Ultimate Wildmutt', 'ultimate-wildmutt', 'Vulpin (Simulated War Evolution)', 'The evolved Vulpimancer featuring thick crimson fur, armor plates, a heavy spiked tail, and crucially: articulate human speech. Ultimate Wildmutt combines predator radar senses with lethal tail-whip strikes and tactical communication.', 'alien', 'published'),
('Ultimate Way Big', 'ultimate-way-big', 'Cosmic Storms (Simulated War Evolution)', 'The evolved To''kustar standing over 250 feet tall, clad in blue-and-red cosmic armor with energy horn blades. Ultimate Way Big can fly through the atmosphere, shoot cosmic energy discs, and was summoned to battle the cosmic god Dagon.', 'alien', 'published'),
('Vilgax', 'vilgax', 'Vilgaxia', 'The ruthless intergalactic warlord who seeks the Omnitrix to build an unstoppable army of drone warriors. Across all three canonical series, Vilgax endures severe cybernetic enhancements, claims the powers of 10 champion heroes, and merges with Dagon.', 'villain', 'published'),
('Kevin Levin', 'kevin-levin', 'Earth', 'An Osmosian who began as a troubled runaway absorbing Omnitrix energy in the 2005 series, causing genetic mutations. Reforming five years later, Kevin becomes Ben''s steadfast best friend and Gwen''s love interest, absorbing solid matter like Taydenite and steel.', 'hero', 'published'),
('Gwen Tennyson', 'gwen-tennyson', 'Earth / Anodyne', 'Ben''s brilliant cousin whose magical aptitude was first discovered in the original series via the Charms of Bezel. In Alien Force and Ultimate Alien, she unlocks her true Anodite heritage, projecting radiant magenta mana shields, stepping disks, and energy constructs.', 'hero', 'published'),
('Ben Tennyson', 'ben-tennyson', 'Earth', 'The central hero of the universe. At age 10, he discovered the Omnitrix in a forest clearing. At 15, he recalibrated the device to fight the Highbreed invasion. At 16, he wielded the Ultimatrix and saved the universe from Aggregor and Dagon.', 'hero', 'published'),
('Aggregor', 'aggregor', 'Osmos V', 'A ruthless Osmosian warlord who kidnapped five alien fugitives from the Andromeda Galaxy. Using his machine, Aggregor absorbed all five aliens at 100% capacity, mutating into Ultimate Aggregor with invulnerable armor, water blasts, hurricanes, nuclear heat, and electrical phasing.', 'villain', 'published')
